import{_ as a,o as e,c as n,a2 as o}from"./chunks/framework.Boholvbs.js";const D=JSON.parse('{"title":"xsync-transfer(1)","description":"Copy locally, push or pull remotely, and choose exactly what a path means.","frontmatter":{"title":"xsync-transfer(1)","description":"Copy locally, push or pull remotely, and choose exactly what a path means.","manual":"xsync-transfer(1)","manualName":"Transfers & paths","sectionNumber":"1"},"headers":[],"relativePath":"transfers.md","filePath":"transfers.md"}'),t={name:"transfers.md"};function l(c,s,p,i,r,d){return e(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="xsync-transfer-1" tabindex="-1">xsync-transfer(1) <a class="header-anchor" href="#xsync-transfer-1" aria-label="Permalink to &quot;xsync-transfer(1)&quot;">​</a></h1><div class="manual-deck"><strong>Transfers &amp; paths</strong><p>Copy locally, push or pull remotely, and choose exactly what a path means.</p></div><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS {#synopsis}&quot;">​</a></h2><div class="example-caption">Transfer form</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs [OPTION]... SRC [SRC]... DEST</span></span></code></pre></div><h2 id="local" tabindex="-1">LOCAL COPY <a class="header-anchor" href="#local" aria-label="Permalink to &quot;LOCAL COPY {#local}&quot;">​</a></h2><div class="example-caption">Copy contents</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><div class="example-caption">Copy the source directory itself</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> src</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>A trailing source slash selects the directory’s contents. Without it, the source basename is included. For example, copying <code>src</code> to an existing <code>dst/</code> creates <code>dst/src/</code>.</p><div class="example-caption">Multiple local sources</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> notes.txt</span><span style="color:#DEDEDE;"> photos/</span><span style="color:#DEDEDE;"> archive/</span></span></code></pre></div><h2 id="remote" tabindex="-1">SSH PUSH AND PULL <a class="header-anchor" href="#remote" aria-label="Permalink to &quot;SSH PUSH AND PULL {#remote}&quot;">​</a></h2><div class="example-caption">Push local files to the host</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-azP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> user@host:/backup/src/</span></span></code></pre></div><div class="example-caption">Pull remote files locally</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-azP</span><span style="color:#DEDEDE;"> user@host:/data/</span><span style="color:#DEDEDE;"> data/</span></span></code></pre></div><p><code>-z</code> compresses remote file data with zstd. It has no compression effect on local copies. A transfer may have one remote endpoint; native remote-to-remote transfers are unsupported.</p><h2 id="listing" tabindex="-1">LISTING <a class="header-anchor" href="#listing" aria-label="Permalink to &quot;LISTING {#listing}&quot;">​</a></h2><div class="example-caption">List immediate entries, or recurse remotely</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">src/</span></span>
<span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-r</span><span style="color:#DEDEDE;"> user@host:/data/</span></span></code></pre></div><div class="example-caption">Inspect sources without modifying the destination</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">--list-only</span><span style="color:#DEDEDE;"> -a</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>A single source argument lists metadata. A slash lists a directory’s immediate contents; <code>-r</code> includes descendants. Listings show type, permissions, byte size, modification time, and names. <code>-l</code> adds symlink targets.</p><h2 id="relative" tabindex="-1">RELATIVE PATHS AND SELECTION <a class="header-anchor" href="#relative" aria-label="Permalink to &quot;RELATIVE PATHS AND SELECTION {#relative}&quot;">​</a></h2><div class="example-caption">Create dst/project/file.txt</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aR</span><span style="color:#DEDEDE;"> /data/./project/file.txt</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>With <code>-R</code>, <code>/./</code> cuts off the path prefix. <code>--files-from</code> selects names relative to a single source root.</p><div class="example-caption">NUL-delimited selection from the current directory</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">find </span><span style="color:#DEDEDE;">.</span><span style="color:#DEDEDE;"> -type</span><span style="color:#DEDEDE;"> f</span><span style="color:#DEDEDE;"> -print0</span><span style="color:#DEDEDE;"> | xs </span><span style="color:#DEDEDE;">-a0</span><span style="color:#DEDEDE;"> --files-from=-</span><span style="color:#DEDEDE;"> ./</span><span style="color:#DEDEDE;"> user@host:backup/</span></span></code></pre></div><aside class="manual-note"><span>NOTE</span><p>With a file list, <code>-a</code> preserves attributes but does not imply recursive directory traversal. Add <code>-r</code> when selected directories should be copied recursively.</p></aside><h2 id="existing" tabindex="-1">EXISTING FILES <a class="header-anchor" href="#existing" aria-label="Permalink to &quot;EXISTING FILES {#existing}&quot;">​</a></h2><div class="example-caption">Create files that are missing at the destination</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> --ignore-existing</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><div class="example-caption">Skip files that are newer on the receiver</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-auP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p><code>--existing</code> skips new files. <code>--ignore-existing</code> skips existing files. <code>-u</code> skips a file when the destination is newer. These are batch transfer policies, not interactive conflict dialogs.</p>`,38)])])}const y=a(t,[["render",l]]);export{D as __pageData,y as default};
